tools.example:
img = ExampleData[{"TestImage", "Coins"}];
template = ImageTrim[img, {{40, 40}, {100, 100}}];
corr = ImageCorrelate[img, template, NormalizedSquaredEuclideanDistance];
ImageAdjust[ColorNegate[corr]]

img = ExampleData[{"TestImage", "House"}];
mask = Image[Rasterize[Graphics[{White, Disk[{0, 0}, 0.2]},
   Background -> Black, ImageSize -> ImageDimensions[img]]], "Bit"];
Inpaint[img, mask]

img = ExampleData[{"TestImage", "Boat"}];
blurred = GaussianFilter[img, 4];
ImageDeconvolve[blurred, GaussianMatrix[4], Method -> "Tikhonov"]
